const trigger = $('Telegram Trigger').first().json;
const msg = trigger.message || {};
const rawText = msg.text || '';
const chatId = msg.chat?.id;
const messageId = msg.message_id;

const inputItem = $input.first();
let rawModel = inputItem.json.content?.parts?.[0]?.text
  || inputItem.json.text
  || inputItem.json.output
  || inputItem.json;
if (typeof rawModel === 'object' && rawModel !== null) {
  // jsonOutput mode may already parse
  if (rawModel.title !== undefined || rawModel.startsAt !== undefined || rawModel.error !== undefined) {
    rawModel = JSON.stringify(rawModel);
  } else if (rawModel.content?.parts?.[0]?.text) {
    rawModel = rawModel.content.parts[0].text;
  } else {
    rawModel = JSON.stringify(rawModel);
  }
}

let clean = String(rawModel || '').replace(/```json|```/g, '').trim();
let ai = null;
try {
  ai = JSON.parse(clean);
  if (Array.isArray(ai)) ai = ai[0] || {};
} catch (e) {
  return [{
    json: {
      ok: false,
      error: 'AI החזיר JSON לא תקין: ' + e.message,
      rawText,
      chatId,
      messageId,
      source: 'hybrid',
    },
  }];
}

if (ai.error || !ai.startsAt) {
  return [{
    json: {
      ok: false,
      error: ai.error || 'לא מצאתי תאריך. שלחו למשל: יום שלישי בשעה 6 תור לרופא',
      rawText,
      chatId,
      messageId,
      source: 'hybrid',
      ai,
    },
  }];
}

let startsAt = new Date(ai.startsAt);
if (Number.isNaN(startsAt.getTime())) {
  return [{
    json: {
      ok: false,
      error: 'תאריך לא תקין מה-AI',
      rawText,
      chatId,
      messageId,
      source: 'hybrid',
      ai,
    },
  }];
}

const hourMentioned = Boolean(ai.hourMentioned);
const durationMentioned = Boolean(ai.durationMentioned);
let durationMinutes = Number(ai.durationMinutes);
if (!Number.isFinite(durationMinutes) || durationMinutes <= 0) {
  durationMinutes = 60;
}
if (!durationMentioned) durationMinutes = durationMinutes || 60;

// Default duration = 1 hour when not mentioned
if (!durationMentioned) durationMinutes = 60;

let timeInferred = !hourMentioned;
const hint = (ai.timeOfDayHint || '').toLowerCase();
const forceMorning = hint === 'morning';
const forceEvening = hint === 'evening' || hint === 'afternoon' || hint === 'night';

// Apply Israeli appointment heuristic: bare hours 1–7 → evening (+12)
// unless morning was implied. Prefer rawHour from AI when present.
let hour = startsAt.getHours();
const rawHour = ai.rawHour == null ? null : Number(ai.rawHour);
if (hourMentioned && rawHour != null && Number.isFinite(rawHour)) {
  let h = rawHour;
  if (!forceMorning && (forceEvening || h <= 7) && h > 0 && h < 12) {
    h += 12;
  }
  startsAt = new Date(
    startsAt.getFullYear(),
    startsAt.getMonth(),
    startsAt.getDate(),
    h,
    startsAt.getMinutes(),
    0,
    0,
  );
} else if (!hourMentioned) {
  // Default time 09:00 Israel wall-clock on that day
  startsAt = new Date(
    startsAt.getFullYear(),
    startsAt.getMonth(),
    startsAt.getDate(),
    9,
    0,
    0,
    0,
  );
  timeInferred = true;
} else if (!forceMorning && (forceEvening || hour <= 7) && hour > 0 && hour < 12) {
  startsAt = new Date(startsAt.getTime() + 12 * 60 * 60 * 1000);
}

const endsAt = new Date(startsAt.getTime() + durationMinutes * 60_000);
let title = String(ai.title || '').trim() || 'אירוע';
if (title.length > 120) title = title.slice(0, 120);

return [{
  json: {
    ok: true,
    title,
    startsAt: startsAt.toISOString(),
    endsAt: endsAt.toISOString(),
    durationMinutes,
    timeInferred,
    durationInferred: !durationMentioned,
    confidence: ai.confidence ?? null,
    rawText,
    chatId,
    messageId,
    source: 'hybrid',
    ai,
  },
}];

